INSERT INTO comments (id, index_id, content, author_id, article_index_id, is_hidden, created_at, updated_at)
VALUES (
        #{id},

            #{indexId}
            DEFAULT
        ,
        #{content}, #{authorId}, #{articleIndexId},


                (SELECT c.is_hidden
                FROM comments c
                WHERE c.index_id = #{indexId}
                LIMIT 1)

            DEFAULT
        ,
        COALESCE(
            (SELECT c.created_at
            FROM comments c
            WHERE c.index_id = #{indexId}
            LIMIT 1),
            #{updatedAt}
        ),
        #{updatedAt}
       )
